generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "sqlite"
  url      = env("DATABASE_URL")
}

model User {
  id        String   @id @default(cuid())
  email     String   @unique
  name      String?
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
}

model Post {
  id        String   @id @default(cuid())
  title     String
  content   String?
  published Boolean  @default(false)
  authorId  String
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  @relation(name = "post_author", refType = "User", refColumn = "id", onDelete = "CASCADE")
}

model Comment {
  id        String   @id @default(cuid())
  content   String
  published Boolean @default(false)
  createdAt DateTime @default(now())
  updatedAt}
